'use strict';
const fleetPage=document.createElement('section');fleetPage.className='fleet-page';fleetPage.hidden=true;fleetPage.innerHTML='<div class="fleet-heading"><div><h2>我的机型收藏册</h2><p id="fleet-count"></p></div><input type="search" id="fleet-search" placeholder="搜索机型" aria-label="搜索机型"></div><p id="fleet-missing"></p><div class="fleet-grid" id="fleet-grid"></div>';document.querySelector('main').append(fleetPage);
const fleetNav=document.createElement('button');fleetNav.type='button';fleetNav.dataset.view='fleet';fleetNav.textContent='机型收藏册';document.querySelector('.view-links').append(fleetNav);
const fleetDialog=document.createElement('dialog');fleetDialog.className='flight-dialog';fleetDialog.innerHTML='<div class="dialog-heading"><h2 id="fleet-detail-title"></h2><button type="button" class="dialog-close" id="fleet-close" aria-label="关闭">×</button></div><div id="fleet-detail"></div>';document.body.append(fleetDialog);$('fleet-close').onclick=()=>fleetDialog.close();
function fleetKey(value){return String(value||'').trim().replace(/\s+/g,' ');}
function fleetGroups(){const groups=new Map();let missing=0;for(const r of state.rows||[]){const date=dateValue(r.date);if(!date||date>localDate()||recordCanceled(r))continue;const name=fleetKey(r.aircraft);if(!name){missing++;continue;}const canonical=catalogAircraft(name)?.name||name;const key=canonical.toLowerCase();if(!groups.has(key))groups.set(key,{name:canonical,rows:[]});groups.get(key).rows.push(r);}return {groups:[...groups.values()].sort((a,b)=>b.rows.length-a.rows.length||a.name.localeCompare(b.name)),missing};}
function fleetSpecial(name){return /\b(?:a?380|b?747)(?:\b|[- ])/i.test(name)||(!/airbus|boeing|\b[ab][2378]\d\d/i.test(name));}
function fleetDetail(g){$('fleet-detail-title').textContent=g.name;const box=$('fleet-detail');box.replaceChildren();for(const r of [...g.rows].sort((a,b)=>dateValue(b.date).localeCompare(dateValue(a.date)))){const row=document.createElement('div');row.className='fleet-leg';const title=document.createElement('strong');title.textContent=`${recordAirportName(r.from)} → ${recordAirportName(r.to)}`;const sub=document.createElement('span');sub.textContent=`${dateValue(r.date)} · ${normalizeAirlineCode(r.airline)} ${r.flight||''} · ${airportCode(r.from)} → ${airportCode(r.to)}`;row.append(title,sub);box.append(row);}fleetDialog.showModal();}
function renderFleet(){const {groups,missing}=fleetGroups();const collected=new Set(groups.map(g=>g.name));const pending=aircraftCatalog.filter(a=>!collected.has(a.name)).map(a=>({...a,rows:[],pending:true}));const mode=$('fleet-status')?.value||'all',entries=[...groups,...pending].filter(g=>mode==='all'||(mode==='flown'?!g.pending:g.pending));const query=$('fleet-search').value.trim().toLowerCase();$('fleet-count').textContent=`已收藏 ${groups.length} 种机型 · ${groups.reduce((n,g)=>n+g.rows.length,0)} 次飞行`;$('fleet-missing').textContent=missing?`${missing} 条历史行程尚未填写机型，可在航班记录中补齐。`:'';const box=$('fleet-grid');box.replaceChildren();for(const g of entries.filter(g=>g.name.toLowerCase().includes(query))){const button=document.createElement('button');button.type='button';button.className='fleet-card'+(g.pending?' fleet-pending':'');const icon=document.createElement('div');icon.className='fleet-icon';icon.textContent='✈';const title=document.createElement('h3');title.textContent=g.name;const detail=document.createElement('p');const airlines=new Set(g.rows.map(r=>normalizeAirlineCode(r.airline)).filter(Boolean)),routes=new Set(g.rows.map(r=>[airportCode(r.from),airportCode(r.to)].join('→')));detail.textContent=`${g.rows.length} 次飞行 · ${airlines.size} 家航司 · ${routes.size} 条单向航线`;const dates=g.rows.map(r=>dateValue(r.date)).sort();const first=document.createElement('small');first.textContent=g.pending?'等待你的第一次乘坐':`首次乘坐 ${dates[0]}`;const tag=document.createElement('span');tag.className='fleet-tag';tag.textContent=g.pending?'待打卡':fleetSpecial(g.name)?'特别收藏':'已打卡';button.append(icon,tag,title,detail,first);button.onclick=()=>{if(!g.pending){fleetDetail(g);return;}$('fleet-detail-title').textContent=g.name;const box=$('fleet-detail');box.replaceChildren();const note=document.createElement('p');note.textContent='还没有乘坐记录。新增并填写该机型的历史航班后，会自动点亮。';const link=document.createElement('a');link.href=g.source;link.target='_blank';link.rel='noopener noreferrer';link.textContent='查看机型 / 机队来源';box.append(note,link);fleetDialog.showModal();};box.append(button);}if(!box.children.length){const empty=document.createElement('p');empty.textContent=groups.length?'没有匹配的机型。':'添加已飞行且填写了机型的航班，开启你的收藏册。';box.append(empty);}}
const originalShowWorkspace=showWorkspace;showWorkspace=function(view){originalShowWorkspace(view==='fleet'?'records':view);fleetPage.hidden=view!=='fleet';if(view==='fleet'){records.hidden=true;workspace.hidden=true;$('workspace-title').textContent='每一种飞机，一段新的记忆。';$('workspace-description').textContent='从历史行程中收集你乘坐过的机型。';document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view==='fleet')b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});renderFleet();}};
fleetNav.onclick=()=>showWorkspace('fleet');$('fleet-search').oninput=renderFleet;window.addEventListener('atlas:rows',renderFleet);renderFleet();

const fleetFilter=document.createElement('select');fleetFilter.id='fleet-status';fleetFilter.setAttribute('aria-label','收藏状态');fleetFilter.innerHTML='<option value="all">全部机型</option><option value="flown">已乘坐</option><option value="pending">待打卡</option>';document.querySelector('.fleet-heading').append(fleetFilter);fleetFilter.onchange=renderFleet;const catalogNote=document.createElement('p');catalogNote.className='fleet-catalog-note';catalogNote.textContent=`待打卡目录：${aircraftCatalog.length} 种常见在役客机 · ${aircraftCatalogChecked} 核对。非实时、非全球完整目录；机型卡片可查看来源。`;document.querySelector('.fleet-heading').after(catalogNote);renderFleet();

const fleetSources=document.createElement('details');fleetSources.className='fleet-catalog-note';const sourceHeading=document.createElement('summary');sourceHeading.textContent='机型资料来源';fleetSources.append(sourceHeading);for(const [name,url] of Object.entries(aircraftCatalogSources)){const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=name;link.style.marginRight='12px';fleetSources.append(link);}document.querySelector('.fleet-catalog-note').after(fleetSources);
